import assert from 'node:assert/strict';
import {readFileSync, readdirSync, statSync} from 'node:fs';
import {join} from 'node:path';
const read = p => readFileSync(p, 'utf8');
const walk = d => readdirSync(d).flatMap(n => { const p = join(d, n); return statSync(p).isDirectory() ? walk(p) : [p]; });
const count = (s, re) => (s.match(re) || []).length;
// RULE-04 test-only fixture bridge markers must never reach a shipped bundle.
const BRIDGE = [/createScenarioRuntime/, /assertScenarioState/, /RULE-04-test-only/, /rule04-fixture/, /lorcana-rule04-/, /withScenarioRuntime/, /chosenOperationGroups/];
const kernel = read('vendor/tcg-engines/dist/kernel.js');
for (const re of [/Math\.random/, /randomUUID/, /getRandomValues/, /seedrandom/, /createHmac/, /randomBytes/, /node:crypto/, /raw-suite-legacy/, /installQualificationDefaults/, /\bBun\b/, /lorcana-rng/, /completed-private-replay/, ...BRIDGE.filter(re => !/chosenOperationGroups/.test(String(re)))])
  assert.equal(count(kernel, new RegExp(re, 'g')), 0, 'kernel contains ' + re);
const clocks = [...kernel.matchAll(/Date\.now\(\)|performance\.now\(\)/g)].map(m => kernel.slice(Math.max(0, m.index - 80), m.index + 40));
assert.ok(clocks.every(c => /timestamp: Date\.now\(\)/.test(c) || /\? performance\.now\(\) : Date\.now\(\)/.test(c)), 'unexpected kernel clock read');
assert.equal(count(kernel, /Captured clock required/g), 1); assert.equal(count(kernel, /Legacy random helper/g), 1);
const lab = read('packages/engine-lab/dist/lab-worker.js') + read('packages/engine-lab/dist/index.js');
for (const re of [/createHmac/, /node:crypto/, /verifyCompletedReplay/, /seedCommitment/, /completed-private-replay/, /server-match-seed/, /lorcana-rng/, /exportReplay/, /engine-adapter/, /raw-suite-legacy/, /installQualificationDefaults/, ...BRIDGE.filter(re => !/chosenOperationGroups/.test(String(re)))])
  assert.equal(count(lab, new RegExp(re, 'g')), 0, 'lab contains ' + re);
const server = readdirSync('packages/engine-adapter/dist').filter(n => n.endsWith('.js')).map(n => read(join('packages/engine-adapter/dist', n))).join('\n');
assert.equal(count(server, /seedrandom/g), 0, 'server adapter contains seedrandom');
for (const re of BRIDGE.slice(0, 6)) assert.equal(count(server, new RegExp(re, 'g')), 0, 'server adapter contains ' + re);
for (const re of [/gain-ink-drop-counters/, /Adventurous/, /source-zone-incarnation/, /keyword-vanish/]) assert.ok(re.test(kernel), 'kernel lacks reviewed RULE-04 mechanic ' + re);
assert.ok(/createHmac/.test(server) && /randomBytes\(32\)/.test(server));
const apps = ['apps/web/dist', 'apps/api/dist', 'apps/match-service/dist', 'apps/worker/dist'].filter(d => { try { return statSync(d).isDirectory(); } catch { return false; } });
const appFiles = apps.flatMap(walk).filter(p => /\.(js|mjs|cjs|html|css|map)$/.test(p));
for (const p of appFiles) { const s = read(p); for (const re of [/createSyntheticKernel/, /createHmac/, /seedCommitment/, /verifyCompletedReplay/, /lorcana-rng/, /seedrandom/, /completed-private-replay/, ...BRIDGE]) assert.ok(!re.test(s), p + ' contains ' + re); }
console.log(JSON.stringify({kernelBytes: kernel.length, kernelClockReads: clocks.length, labBytes: lab.length, serverFiles: readdirSync('packages/engine-adapter/dist').filter(n => n.endsWith('.js')).length, appDirs: apps, appFiles: appFiles.length}));
console.log('PASS compiled kernel has no ambient entropy/Bun/raw-suite defaults (clock reads only in log timestamps/cache telemetry) and contains the reviewed RULE-04 mechanics; Lab bundle has no server RNG/replay; server has no seedrandom; no kernel/Lab/server/app bundle contains the RULE-04 test-only fixture bridge; app bundles contain no engine RNG/replay');
